coding.referenceSolution:
INSERT INTO inventory (sku, qty) VALUES ('A1', 5)
ON CONFLICT (sku) DO UPDATE SET qty = inventory.qty + excluded.qty;

SELECT sku, qty FROM inventory ORDER BY sku;

coding.starterCode:
WITH ranked AS (
  SELECT customer_id, id AS order_id,
         ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at) AS rn
  FROM orders
)
SELECT customer_id, order_id FROM ranked WHERE rn = 1 ORDER BY customer_id;

coding.referenceSolution:
WITH ranked AS (
  SELECT customer_id, id AS order_id,
         ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC) AS rn
  FROM orders
)
SELECT customer_id, order_id FROM ranked WHERE rn = 1 ORDER BY customer_id;

coding.starterCode:
WITH r AS (
  SELECT day, amount, LEAD(amount) OVER (ORDER BY day) AS previous FROM revenue
)
SELECT day, amount, previous FROM r WHERE amount < previous ORDER BY day;

coding.referenceSolution:
WITH r AS (
  SELECT day, amount, LAG(amount) OVER (ORDER BY day) AS previous FROM revenue
)
SELECT day, amount, previous FROM r WHERE amount < previous ORDER BY day;
